-- Player history over existing snapshots; run as warehouse administrator. No credentials.
CREATE OR REPLACE VIEW vatican_bi.player_activity SQL SECURITY DEFINER AS
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('run:',toString(run_id)) AS `record_id`, toString(run_id) AS `reference_id`, 'run' AS `activity_type`, 'Забег' AS `activity_label`, concat(transform(outcome, ['victory', 'defeat'], ['Победа', 'Поражение'], concat('Код: ',toString(outcome))), '; церковь ',toString(church_level),'; герой ',toString(hero_kills),'; башни ',toString(tower_kills),'; улучшения ',toString(building_upgrades)) AS `detail`, transform(outcome, ['victory', 'defeat'], ['Победа', 'Поражение'], concat('Код: ',toString(outcome))) AS `outcome_name`, toUInt32(church_level) AS `church_level`, toDecimal128(hero_kills,0) AS `hero_kills`, toDecimal128(tower_kills,0) AS `tower_kills`, toDecimal128(building_upgrades,0) AS `building_upgrades`, toDecimal128(xp_granted,0) AS `run_xp`, CAST(NULL AS Nullable(Decimal(38,0))) AS `xp_delta`, CAST(NULL AS Nullable(Int64)) AS `levels_gained`, CAST(NULL AS Nullable(String)) AS `offer_name`, CAST(NULL AS Nullable(String)) AS `currency_name`, CAST(NULL AS Nullable(String)) AS `currency_code`, CAST(NULL AS Nullable(Decimal(38,0))) AS `charged_amount` FROM `vatican_bi`.`runs_snapshot`
UNION ALL
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('xp:',toString(event_id)) AS `record_id`, toString(event_id) AS `reference_id`, 'xp' AS `activity_type`, 'Начисление XP' AS `activity_label`, concat('+',toString(xp_delta),' XP; уровень ',toString(level_after)) AS `detail`, CAST(NULL AS Nullable(String)) AS `outcome_name`, CAST(NULL AS Nullable(UInt32)) AS `church_level`, CAST(NULL AS Nullable(Decimal(38,0))) AS `hero_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `tower_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `building_upgrades`, CAST(NULL AS Nullable(Decimal(38,0))) AS `run_xp`, xp_delta AS `xp_delta`, CAST(NULL AS Nullable(Int64)) AS `levels_gained`, CAST(NULL AS Nullable(String)) AS `offer_name`, CAST(NULL AS Nullable(String)) AS `currency_name`, CAST(NULL AS Nullable(String)) AS `currency_code`, CAST(NULL AS Nullable(Decimal(38,0))) AS `charged_amount` FROM `vatican_bi`.`xp_snapshot`
UNION ALL
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('level:',toString(event_id)) AS `record_id`, toString(event_id) AS `reference_id`, 'level' AS `activity_type`, 'Повышение уровня' AS `activity_label`, concat(toString(old_level),' → ',toString(new_level),' (+',toString(levels_gained),')') AS `detail`, CAST(NULL AS Nullable(String)) AS `outcome_name`, CAST(NULL AS Nullable(UInt32)) AS `church_level`, CAST(NULL AS Nullable(Decimal(38,0))) AS `hero_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `tower_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `building_upgrades`, CAST(NULL AS Nullable(Decimal(38,0))) AS `run_xp`, CAST(NULL AS Nullable(Decimal(38,0))) AS `xp_delta`, levels_gained AS `levels_gained`, CAST(NULL AS Nullable(String)) AS `offer_name`, CAST(NULL AS Nullable(String)) AS `currency_name`, CAST(NULL AS Nullable(String)) AS `currency_code`, CAST(NULL AS Nullable(Decimal(38,0))) AS `charged_amount` FROM `vatican_bi`.`level_ups_snapshot`
UNION ALL
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('gift:',toString(claim_id)) AS `record_id`, toString(claim_id) AS `reference_id`, 'gift' AS `activity_type`, 'Подарок за уровень' AS `activity_label`, concat('За уровень ',toString(rewarded_level),'; набор ',toString(reward_bundle_id)) AS `detail`, CAST(NULL AS Nullable(String)) AS `outcome_name`, CAST(NULL AS Nullable(UInt32)) AS `church_level`, CAST(NULL AS Nullable(Decimal(38,0))) AS `hero_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `tower_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `building_upgrades`, CAST(NULL AS Nullable(Decimal(38,0))) AS `run_xp`, CAST(NULL AS Nullable(Decimal(38,0))) AS `xp_delta`, CAST(NULL AS Nullable(Int64)) AS `levels_gained`, CAST(NULL AS Nullable(String)) AS `offer_name`, CAST(NULL AS Nullable(String)) AS `currency_name`, CAST(NULL AS Nullable(String)) AS `currency_code`, CAST(NULL AS Nullable(Decimal(38,0))) AS `charged_amount` FROM `vatican_bi`.`level_gifts_snapshot`
UNION ALL
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('case:',toString(opening_id)) AS `record_id`, toString(opening_id) AS `reference_id`, 'case' AS `activity_type`, 'Открытие кейса' AS `activity_label`, concat(case_code,'; ',transform(rarity, ['COMMON', 'RARE', 'EPIC', 'LEGENDARY'], ['Обычная', 'Редкая', 'Эпическая', 'Легендарная'], concat('Код: ',toString(rarity))),'; гарант ',if(guaranteed_triggered=1,'да','нет'),'; счётчик до ',toString(pity_before)) AS `detail`, CAST(NULL AS Nullable(String)) AS `outcome_name`, CAST(NULL AS Nullable(UInt32)) AS `church_level`, CAST(NULL AS Nullable(Decimal(38,0))) AS `hero_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `tower_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `building_upgrades`, CAST(NULL AS Nullable(Decimal(38,0))) AS `run_xp`, CAST(NULL AS Nullable(Decimal(38,0))) AS `xp_delta`, CAST(NULL AS Nullable(Int64)) AS `levels_gained`, CAST(NULL AS Nullable(String)) AS `offer_name`, CAST(NULL AS Nullable(String)) AS `currency_name`, CAST(NULL AS Nullable(String)) AS `currency_code`, CAST(NULL AS Nullable(Decimal(38,0))) AS `charged_amount` FROM `vatican_bi`.`case_openings_snapshot`
UNION ALL
SELECT toString(player_id) AS `player_id`, occurred_at AS `occurred_at`, concat('purchase:',toString(purchase_id)) AS `record_id`, toString(purchase_id) AS `reference_id`, 'purchase' AS `activity_type`, 'Покупка / выдача' AS `activity_label`, concat(offer_id,'; ',if(charged_amount=0,'бесплатно',concat(toString(charged_amount),' ',if(currency_code='PRESTIGE','Престиж',currency_code)))) AS `detail`, CAST(NULL AS Nullable(String)) AS `outcome_name`, CAST(NULL AS Nullable(UInt32)) AS `church_level`, CAST(NULL AS Nullable(Decimal(38,0))) AS `hero_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `tower_kills`, CAST(NULL AS Nullable(Decimal(38,0))) AS `building_upgrades`, CAST(NULL AS Nullable(Decimal(38,0))) AS `run_xp`, CAST(NULL AS Nullable(Decimal(38,0))) AS `xp_delta`, CAST(NULL AS Nullable(Int64)) AS `levels_gained`, offer_id AS `offer_name`, if(currency_code='PRESTIGE','Престиж',currency_code) AS `currency_name`, currency_code AS `currency_code`, charged_amount AS `charged_amount` FROM `vatican_bi`.`shop_purchases_snapshot`;
